'''/**
 * Every live issue of a project, walking the cursor to the end. Work that must
 * see the whole project (cloning, indexing) cannot stop at one page.
 */
export async function listLiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const all: Issue[] = [];
  let cursor: string | null = null;
  do {
    const page: Page<Issue> = await listIssues({
      orgId,
      projectId,
      limit: 100,
      cursor,
    });
    all.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);
  return all;
}

