): Promise<Project> {''',
'''/**
 * Clones a live project into a new one of the same workspace, optionally with
 * its live issues (ADR 0012). Every gate and quota is checked before the first
 * write, so a refused clone leaves nothing behind. The clone's description,
 * visibility, colour and lead come from the source; its status is `active` and
 * it has no target date. Copied issues keep their title, description, priority,
 * estimate, due date and labels, and are renumbered from 1 in source order.
 * Their status is the workspace default, and they are unassigned. Comments,
 * attachments and links are not copied. One `project.cloned` event is published
 * (no `project.created`, no per-issue `issue.created`); search and usage follow
 * from that event.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const projectsUsed = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", projectsUsed)) {
    throw new Error(
      `Plan ${org.plan} allows ${projectsUsed} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? [...(await issueRepo.listLiveIssuesForProject(input.orgId, source.id))]
        .sort((a, b) => a.number - b.number)
    : [];
  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)) {
    throw new Error(
      `Plan ${org.plan} allows fewer issues per project than the ${sourceIssues.length} to be copied`,
    );
  }

  const clone = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const status = issueStatusSchema.safeParse(org.settings.defaultIssueStatus);
  const defaultStatus = status.success ? status.data : "backlog";

  let issuesCopied = 0;
  for (const issue of sourceIssues) {
    issuesCopied += 1;
    await issueRepo.insertIssue(
      {
        orgId: input.orgId,
        projectId: clone.id,
        title: issue.title,
        description: issue.description,
        status: defaultStatus,
        priority: issue.priority,
        assigneeId: null,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        labelIds: [...issue.labelIds],
      },
      actor.userId,
      issuesCopied,
    );
  }

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: clone.id,
    sourceProjectId: source.id,
    issuesCopied,
  });

  return clone;
}

